window.SAOMD_STORIES[410400701]={"id":410400701,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410400701:1:1","speaker":"Alice","text":"...","pose":10540107,"background":"bg_event_alo_sky_night","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"..."},{"uid":"410400701:1:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":2,"order":2,"actions":[{"uid":"410400701:2:1","speaker":"Eugeo","text":"Are you upset, Alice?","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"爱丽丝，你不高兴吗？"}]},{"id":3,"order":3,"actions":[{"uid":"410400701:3:1","speaker":"Alice","text":"No. Should I be?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"没有。我应该这样吗？"},{"uid":"410400701:3:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":4,"order":4,"actions":[{"uid":"410400701:4:1","speaker":"Kirito","text":"D-Don't let it bug you, okay?\nIt's not like this is the first\ntime we've been trolled.","pose":100115022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"别、别让它困扰你，好吗？这已经不是我们第一次被恶搞了。"},{"uid":"410400701:4:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":5,"order":5,"actions":[{"uid":"410400701:5:1","speaker":"Alice","text":"Trolled?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"被拖拽？"},{"uid":"410400701:5:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":6,"order":6,"actions":[{"uid":"410400701:6:1","speaker":"Asuna","text":"He's talking about the bogus info\nwe got.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"他说的是我们得到的虚假信息。"},{"uid":"410400701:6:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":7,"order":7,"actions":[{"uid":"410400701:7:1","speaker":"Asuna","text":"We came here to find that \"crazy\nunique item near Arun,\" right?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们来这里是为了寻找“阿伦附近疯狂的独特物品”，对吧？"}]},{"id":8,"order":8,"actions":[{"uid":"410400701:8:1","speaker":"Asuna","text":"But it wasn't a Divine Object.\nIt wasn't even rare.\nThe whole story was a fake.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但不是神器。这甚至并不罕见。整个故事都是假的。"},{"uid":"410400701:8:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":9,"order":9,"actions":[{"uid":"410400701:9:1","speaker":"Alice","text":"Spreading of falsehoods is a sin.\nWhy is sin so rampant in this\nworld?!","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"传播谎言是一种罪过。为什么这个世界上罪恶如此猖獗？"},{"uid":"410400701:9:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":10,"order":10,"actions":[{"uid":"410400701:10:1","speaker":"Kirito","text":"Well, information has value.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯，信息有价值。"},{"uid":"410400701:10:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":11,"order":11,"actions":[{"uid":"410400701:11:1","speaker":"Kirito","text":"Some people here make a living as\ninformation brokers, and they buy\nand sell rumors for cash.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这里有些人以信息掮客为生，通过买卖谣言换取现金。"}]},{"id":12,"order":12,"actions":[{"uid":"410400701:12:1","speaker":"Kirito","text":"Some of them are trustworthy,\nbut some of them spread false info\njust for the laughs.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"有些人是值得信赖的，但有些人只是为了搞笑而传播虚假信息。"},{"uid":"410400701:12:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":13,"order":13,"actions":[{"uid":"410400701:13:1","speaker":"Alice","text":"Then I shall find these\nblackguards and strike them down.\nEvil will not be tolerated.","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那我就找到这些无赖，把他们打倒。邪恶不会被容忍。"},{"uid":"410400701:13:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":14,"order":14,"actions":[{"uid":"410400701:14:1","speaker":"Eugeo","text":"H-Hey, take it easy, Alice.\nIt's late, so can we go home?","pose":105302042,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嘿、嘿，别紧张，爱丽丝。时间很晚了，我们可以回家了吗？"},{"uid":"410400701:14:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":15,"order":15,"actions":[{"uid":"410400701:15:1","speaker":"Asuna","text":"Yeah, I'm with Eugeo here.\nLook, we're almost back to Ainc-","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是的，我是尤吉欧。看，我们快要回到Ainc了——"},{"uid":"410400701:15:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":16,"order":16,"actions":[{"uid":"410400701:16:1","speaker":"Asuna","text":"Wait, what?!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"等等，什么？！"}]},{"id":17,"order":17,"actions":[{"uid":"410400701:17:1","speaker":"Kirito","text":"That's not Aincrad!","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那不是艾恩葛朗特！"},{"uid":"410400701:17:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":18,"order":18,"actions":[{"uid":"410400701:18:1","speaker":"Alice","text":"It does appear to be a floating\ncastle, but it's not the one I am\nfamiliar with.","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"看起来确实是一座漂浮城堡，但不是我熟悉的那种。"},{"uid":"410400701:18:2","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":19,"order":19,"actions":[{"uid":"410400701:19:1","speaker":"Eugeo","text":"Agreed. It's still far away,\nand it's hard to make out\nin this light...","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"同意。距离还很远，在这样的光线下很难看清……"}]},{"id":20,"order":20,"actions":[{"uid":"410400701:20:1","speaker":"Eugeo","text":"It's too small, and something\nabout it's just...spooky.","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"太小了，而且有些东西……很诡异。"},{"uid":"410400701:20:2","speaker":"Alice","text":"","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":21,"order":21,"actions":[{"uid":"410400701:21:1","speaker":"Kirito","text":"You can say that again...\nBut if it's not Aincrad,\nwhat is it?","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你再说一遍……但如果不是艾恩葛朗特，那又是什么？"},{"uid":"410400701:21:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":22,"order":22,"actions":[{"uid":"410400701:22:1","speaker":"Yui","text":"That, everyone, is the latest\nupdate! It's an all-new\nHalloween-themed area!","pose":20090205,"background":"bg_17_restaurant_night","item":"","illustration":"","speaker_zh":"结衣","text_zh":"各位，这就是最新的更新啦！这是一个全新的万圣节主题区域！"},{"uid":"410400701:22:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400701:22:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":23,"order":23,"actions":[{"uid":"410400701:23:1","speaker":"Yui","text":"Aincrad was replaced with another\nfloating castle, nicknamed the\n\"Dread Bastion.\"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"艾恩葛朗特被另一座漂浮城堡取代，绰号“恐惧堡垒”。"}]},{"id":24,"order":24,"actions":[{"uid":"410400701:24:1","speaker":"Kirito","text":"Okay, sure. I'm definitely getting\nspooky Halloween vibes from\nthis place.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好的，当然。我肯定从这个地方感受到了恐怖的万圣节氛围。"}]},{"id":25,"order":25,"actions":[{"uid":"410400701:25:1","speaker":"Asuna","text":"But Halloween or not, how could\nthey just go and take away Aincrad\nlike that? Talk about rude...","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不管是不是万圣节，他们怎么可能就这样把艾恩葛朗特拿走呢？谈论粗鲁..."},{"uid":"410400701:25:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410400701:25:3","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":26,"order":26,"actions":[{"uid":"410400701:26:1","speaker":"Eugeo","text":"What's going on?! Is this the work\nof the Forces of Darkness or\ntheir ilk?!","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"这是怎么回事？！这是黑暗势力还是他们的同类所为？！"},{"uid":"410400701:26:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":27,"order":27,"actions":[{"uid":"410400701:27:1","speaker":"Eugeo","text":"Did they use some form of foul\nsorcery to destroy Aincrad?!","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"他们是不是使用了某种邪恶的巫术来摧毁艾恩葛朗特？！"}]},{"id":28,"order":28,"actions":[{"uid":"410400701:28:1","speaker":"Alice","text":"Your home... It's gone...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你的家……没了……"},{"uid":"410400701:28:2","speaker":"Eugeo","text":"","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":29,"order":29,"actions":[{"uid":"410400701:29:1","speaker":"Kirito","text":"Yeah, it's gone. However, I bet if\nwe conquer that castle, Aincrad\nwill return safe and sound.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊，没了。不过，我敢打赌，如果我们攻克了那座城堡，艾恩葛朗特就会安然无恙地回来。"},{"uid":"410400701:29:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410400701:29:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":30,"order":30,"actions":[{"uid":"410400701:30:1","speaker":"Kirito","text":"Let's take a minute to get ready,\nthen bust into that bastion!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们先准备一下，然后冲进那个堡垒！"},{"uid":"410400701:30:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400701:30:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":31,"order":31,"actions":[{"uid":"410400701:31:1","speaker":"Alice","text":"Okay. It's regrettable that\nwe cannot continue seach of\nthe Divine Object though.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"好的。遗憾的是，我们无法继续搜索神器。"},{"uid":"410400701:31:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":32,"order":32,"actions":[{"uid":"410400701:32:1","speaker":"Alice","text":"We have no choice if we\nwish to recover our base of\noperations.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"如果我们想恢复我们的基地，我们别无选择。"},{"uid":"410400701:32:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":33,"order":33,"actions":[{"uid":"410400701:33:1","speaker":"Yui","text":"Umm, sorry to ruin the mood, but\nthe quest reward's been announced\nand I thought I'd share...","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"嗯，抱歉破坏了大家的心情，不过任务奖励已经公布了，我想我应该分享一下……"},{"uid":"410400701:33:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400701:33:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":34,"order":34,"actions":[{"uid":"410400701:34:1","speaker":"Yui","text":"It appears to be another one of\nthe Divine Objects that you've\nbeen collecting.","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"看来又是你收藏的一件神器了。"}]},{"id":35,"order":35,"actions":[{"uid":"410400701:35:1","speaker":"Kirito","text":"S-Seriously?!","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"真的、认真的吗？！"}]},{"id":36,"order":36,"actions":[{"uid":"410400701:36:1","speaker":"Yui","text":"That's right. Take a look!","pose":20090202,"background":"","item":"item_event_sacred_treasure","illustration":"","speaker_zh":"结衣","text_zh":"没错。看看吧！"},{"uid":"410400701:36:2","speaker":"Kirito","text":"","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400701:36:3","speaker":"Asuna","text":"","pose":100209082,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":37,"order":37,"actions":[{"uid":"410400701:37:1","speaker":"Eugeo","text":"Hmm... That does look like the\nother ones we've found so far.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"嗯……这确实和我们目前发现的其他的很像。"},{"uid":"410400701:37:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":38,"order":38,"actions":[{"uid":"410400701:38:1","speaker":"Alice","text":"You mentioned a \"quest reward.\" So\nwe will receive this Divine Object\nif we purge the castle, correct?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你提到了“任务奖励”。那么如果我们净化城堡，我们就会收到这个神器，对吗？"},{"uid":"410400701:38:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":39,"order":39,"actions":[{"uid":"410400701:39:1","speaker":"Asuna","text":"That's right.","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是啊。"},{"uid":"410400701:39:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410400701:39:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":40,"order":40,"actions":[{"uid":"410400701:40:1","speaker":"Alice","text":"Then let me ask you this: how,\nexactly, did your daughter come\nby this information?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那我问你，你女儿到底是怎么得到这个信息的？"},{"uid":"410400701:40:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":41,"order":41,"actions":[{"uid":"410400701:41:1","speaker":"Kirito","text":"Er, well... You see...\nYui's...just...good at gathering\ninformation? Aha. Ha ha.","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呃，那个……你看……结衣的……只是……擅长收集情报？啊哈。哈哈。"},{"uid":"410400701:41:2","speaker":"Asuna","text":"","pose":100209022,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400701:41:3","speaker":"Yui","text":"","pose":200902022,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":42,"order":42,"actions":[{"uid":"410400701:42:1","speaker":"Alice","text":"I see. Then we should consider the\npossibility that this is another\nfalsehood spread by our foes.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"原来如此。那么我们应该考虑这可能是我们的敌人散布的另一个谎言。"},{"uid":"410400701:42:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":43,"order":43,"actions":[{"uid":"410400701:43:1","speaker":"Eugeo","text":"Good point! The Forces of Darkness\nwouldn't hesitate to spread lies\nto further their own ends...","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"说得好！黑暗势力为了达到自己的目的，会毫不犹豫地散布谎言……"},{"uid":"410400701:43:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":44,"order":44,"actions":[{"uid":"410400701:44:1","speaker":"Asuna","text":"I...don't think that's very\nlikely...","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我……我觉得不太可能……"},{"uid":"410400701:44:2","speaker":"Kirito","text":"","pose":100115052,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400701:44:3","speaker":"Yui","text":"","pose":200902052,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":45,"order":45,"actions":[{"uid":"410400701:45:1","speaker":"Kirito","text":"Hey Asuna? Yui?\nCan I borrow you for a sec?","pose":100115042,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嘿亚丝娜？ 结衣？我可以借你一下吗？"}]},{"id":46,"order":46,"actions":[{"uid":"410400701:46:1","speaker":"Asuna","text":"That reward's definitely a Divine\nObject.","pose":10020902,"background":"bg_17_swilvane_town","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"那个奖励绝对是神物啊。"}]},{"id":47,"order":47,"actions":[{"uid":"410400701:47:1","speaker":"Kirito","text":"Oh yeah, for sure.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哦，是的，当然。"}]},{"id":48,"order":48,"actions":[{"uid":"410400701:48:1","speaker":"Yui","text":"I'm sorry. I didn't mean to reveal\nmeta information and confuse them,\nbut it just slipped out...","pose":20090206,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"对不起。我并不是有意透露元信息并迷惑他们，但它只是溜走了......"}]},{"id":49,"order":49,"actions":[{"uid":"410400701:49:1","speaker":"Kirito","text":"Don't worry about it, Yui.\nI'll figure out some way to\nchange the subject.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"别担心，结衣。我会想办法改变话题的。"}]},{"id":50,"order":50,"actions":[{"uid":"410400701:50:1","speaker":"Kirito","text":"We can't really just say,\n\"It's just Halloween, guys!\nYou know, from the real world?\"","pose":100115022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们不能真的只是说，“这只是万圣节，伙计们！你知道，来自现实世界吗？”"}]},{"id":51,"order":51,"actions":[{"uid":"410400701:51:1","speaker":"Asuna","text":"Yeah, that wouldn't end well.\nNow hurry up and smooth things\nover so we can hit that castle!","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是的，这样不会有好结果。现在赶快把事情处理好，这样我们就可以攻击那座城堡了！"}]},{"id":52,"order":52,"actions":[{"uid":"410400701:52:1","speaker":"Kirito","text":"Yeah!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯！"},{"uid":"410400701:52:2","speaker":"アスナ","text":"","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":53,"order":53,"actions":[{"uid":"410400701:53:1","speaker":"Demon","text":"Graaargh!","pose":1,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"恶魔","text_zh":"天啊！"},{"uid":"410400701:53:2","speaker":"Eugeo","text":"","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410400701:53:3","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":54,"order":54,"actions":[{"uid":"410400701:54:1","speaker":"Eugeo","text":"Waagh! What is this thing?!\nIt looks human, but it's purple\nand has bat wings!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哇啊！这是什么东西？！它看起来像人类，但它是紫色的，并且有蝙蝠翅膀！"},{"uid":"410400701:54:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":55,"order":55,"actions":[{"uid":"410400701:55:1","speaker":"Kirito","text":"Classic demon.\nThey're a dime a dozen.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"经典恶魔。他们一毛钱一打。"},{"uid":"410400701:55:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":56,"order":56,"actions":[{"uid":"410400701:56:1","speaker":"Eugeo","text":"A demon, huh? It really looks like\nsomething you'd see in the Forces\nof Darkness, but...","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"恶魔吧？它看起来确实很像你在黑暗力量中看到的东西，但是......"},{"uid":"410400701:56:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":57,"order":57,"actions":[{"uid":"410400701:57:1","speaker":"Asuna","text":"But what, Eugeo?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但是什么，尤吉欧？"},{"uid":"410400701:57:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":58,"order":58,"actions":[{"uid":"410400701:58:1","speaker":"Eugeo","text":"It's just not wicked enough.\nIt's kind of...cute.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"还不够邪恶。这有点……可爱。"},{"uid":"410400701:58:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":59,"order":59,"actions":[{"uid":"410400701:59:1","speaker":"Alice","text":"What's wrong with you? Just what\npart of that thing is \"cute\"?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你怎么了？那东西的哪一部分“可爱”呢？"}]},{"id":60,"order":60,"actions":[{"uid":"410400701:60:1","speaker":"Eugeo","text":"You don't agree? Look at that\nface! It's charming, isn't it?","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你不同意？看看那张脸！很迷人，不是吗？"}]},{"id":61,"order":61,"actions":[{"uid":"410400701:61:1","speaker":"Alice","text":"I...have no words.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我……无话可说。"}]},{"id":62,"order":62,"actions":[{"uid":"410400701:62:1","speaker":"Vampire","text":"I vant to suck your blood!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"吸血鬼","text_zh":"我要吸你的血！"}]},{"id":63,"order":63,"actions":[{"uid":"410400701:63:1","speaker":"Alice","text":"New enemy detected.\nThis one appears to have\nthe gift of speech.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"发现新敌人。这个人似乎有演讲的天赋。"},{"uid":"410400701:63:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":64,"order":64,"actions":[{"uid":"410400701:64:1","speaker":"Kirito","text":"Alice, meet vampire. Vampire,\nAlice. Its hobbies include sucking\nblood and hanging with bats.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"爱丽丝，遇见吸血鬼了。吸血鬼，爱丽丝。它的爱好包括吸血和与蝙蝠悬挂。"},{"uid":"410400701:64:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":65,"order":65,"actions":[{"uid":"410400701:65:1","speaker":"Alice","text":"Repulsive. I shall cleanse this\nworld of its foul taint.","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"令人厌恶。我将清除这个世界的污秽。"},{"uid":"410400701:65:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":66,"order":66,"actions":[{"uid":"410400701:66:1","speaker":"Eugeo","text":"Not unless I kill it first!\nHraaagh!","pose":10530201,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"除非我先杀了它！哈啊！"}]},{"id":67,"order":67,"actions":[{"uid":"410400701:67:1","speaker":"Vampire","text":"Impudent mortals!\nI vill destroy you!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"吸血鬼","text_zh":"无礼的凡人！我要毁了你！"},{"uid":"410400701:67:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400701:67:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":68,"order":68,"actions":[{"uid":"410400701:68:1","speaker":"Asuna","text":"...I suppose Halloween has been\nleaning towards the silly over\nthe scary lately...","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"……我觉得万圣节最近越来越倾向于搞笑而不是恐怖了……"}]},{"id":69,"order":69,"actions":[{"uid":"410400701:69:1","speaker":"Asuna","text":"But I think Eugeo's starting to\nsuspect that something's not\nquite normal here.","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但是我觉得尤吉欧开始怀疑这里有些不太正常了。"}]},{"id":70,"order":70,"actions":[{"uid":"410400701:70:1","speaker":"Kirito","text":"I think they bought my explanation\nearlier...","pose":100115022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我想他们早就相信了我的解释……"}]},{"id":71,"order":71,"actions":[{"uid":"410400701:71:1","speaker":"Kirito","text":"But at this rate, I'll need to\nkeep coming up with ways to\nexplain all this ridiculousness.","pose":100115022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但照这样下去，我得不断想办法来解释这一切的荒谬。"}]},{"id":72,"order":72,"actions":[{"uid":"410400701:72:1","speaker":"Asuna","text":"But we don't have time to ease\nthem into this. The event's only\ngoing on for so long...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但是我们没有时间让他们放松下来。活动只持续这么久..."}]},{"id":73,"order":73,"actions":[{"uid":"410400701:73:1","speaker":"Asuna","text":"And we can't let that Divine\nObject slip by!","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们不能放过那个神物！"}]},{"id":74,"order":74,"actions":[{"uid":"410400701:74:1","speaker":"Kirito","text":"No, we definitely can't!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不，我们绝对不能！"},{"uid":"410400701:74:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":75,"order":75,"actions":[{"uid":"410400701:75:1","speaker":"Werewolf","text":"Awoooooo!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"狼人","text_zh":"呜呜！！"},{"uid":"410400701:75:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410400701:75:3","speaker":"Eugeo","text":"","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":76,"order":76,"actions":[{"uid":"410400701:76:1","speaker":"Eugeo","text":"Ahh! Hey, Kirito?!\nWhat's THIS thing?!","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"啊！嘿，桐人？！这是什么东西？"}]},{"id":77,"order":77,"actions":[{"uid":"410400701:77:1","speaker":"Eugeo","text":"It's walking around like a human,\nbut it's all furry and looks like\na doggy!","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"走路像人，不过浑身毛茸茸的，看起来像小狗！"},{"uid":"410400701:77:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":78,"order":78,"actions":[{"uid":"410400701:78:1","speaker":"Kirito","text":"It's called a werewolf!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这叫狼人！"},{"uid":"410400701:78:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":79,"order":79,"actions":[{"uid":"410400701:79:1","speaker":"Eugeo","text":"Ahahaha, this is great!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"啊哈哈哈，太棒了！"},{"uid":"410400701:79:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":80,"order":80,"actions":[{"uid":"410400701:80:1","speaker":"Alice","text":"Eugeo!\nThis is no time for laughter!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"尤吉欧！现在可不是笑的时候！"}]},{"id":81,"order":81,"actions":[{"uid":"410400701:81:1","speaker":"Alice","text":"Kirito, that goes for you too!\nStop fooling around and help me\ncleanse the castle of these vermin!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"桐人，你也一样！别再胡闹了，帮我清除城堡里的这些害虫吧！"},{"uid":"410400701:81:2","speaker":"Eugeo","text":"","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":82,"order":82,"actions":[{"uid":"410400701:82:1","speaker":"Kirito","text":"R-Right, I'm coming!","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"对、对了，我来了！"},{"uid":"410400701:82:2","speaker":"Asuna","text":"","pose":100209052,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":83,"order":83,"actions":[{"uid":"410400701:83:1","speaker":"Ghost","text":"Booooo...","pose":1,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"幽灵","text_zh":"呜呜……"},{"uid":"410400701:83:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400701:83:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":84,"order":84,"actions":[{"uid":"410400701:84:1","speaker":"Asuna","text":"Wah!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哇！"}]},{"id":85,"order":85,"actions":[{"uid":"410400701:85:1","speaker":"Kirito","text":"Asuna! Are you okay?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"亚丝娜！你还好吗？！"}]},{"id":86,"order":86,"actions":[{"uid":"410400701:86:1","speaker":"Asuna","text":"Y-Yeah... I'm-*gulp*-fine...","pose":100209022,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是、是啊……我——*咕咕*-好吧……"}]},{"id":87,"order":87,"actions":[{"uid":"410400701:87:1","speaker":"Asuna","text":"I just freaked out for a second\nwhen this astral monster spawned,\nthat's all...","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"这个星体怪物出现的时候我只是吓了一跳，仅此而已……"}]},{"id":88,"order":88,"actions":[{"uid":"410400701:88:1","speaker":"Asuna","text":"But I don't mind this ghost that\nmuch. It's actually kind of cute!","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不过我不太介意这个鬼。其实还蛮可爱的！"}]},{"id":89,"order":89,"actions":[{"uid":"410400701:89:1","speaker":"Kirito","text":"Ha ha, yeah. It's good to know\nthat Halloween ghosts don't\ntrigger your phantom phobia!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈，是啊。很高兴知道万圣节鬼魂不会引发您的幽灵恐惧症！"}]},{"id":90,"order":90,"actions":[{"uid":"410400701:90:1","speaker":"Asuna","text":"Hehe, yeah!","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵，是啊！"}]},{"id":91,"order":91,"actions":[{"uid":"410400701:91:1","speaker":"Ghost","text":"RRRWAAAAAAGHHHHHH!!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"幽灵","text_zh":"吼啊啊！"}]},{"id":92,"order":92,"actions":[{"uid":"410400701:92:1","speaker":"Asuna","text":"Awaagh?!","pose":100209082,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哇啊啊？！"}]},{"id":93,"order":93,"actions":[{"uid":"410400701:93:1","speaker":"Kirito","text":"Whoa! It may look cute, but its\nattacks are nothing to laugh\nabout...","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哇哦！虽然看起来很可爱，但是它的攻击却一点都不好笑……"}]},{"id":94,"order":94,"actions":[{"uid":"410400701:94:1","speaker":"Asuna","text":"Y-Yeah... It's not scary, but\nthat doesn't mean it's not\na threat... I'll be more careful.","pose":100209072,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是、是啊……不可怕，但不代表没有威胁……我会更加小心的。"}]},{"id":95,"order":95,"actions":[{"uid":"410400701:95:1","speaker":"Kirito","text":"Good idea. All the monsters here\nare actually pretty tough.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"好主意。这里的怪物其实都很强悍。"}]},{"id":96,"order":96,"actions":[{"uid":"410400701:96:1","speaker":"Kirito","text":"Hmm... Hold up!","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……等等！"}]},{"id":97,"order":97,"actions":[{"uid":"410400701:97:1","speaker":"Asuna","text":"What is it, Kirito?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人，什么事？"}]},{"id":98,"order":98,"actions":[{"uid":"410400701:98:1","speaker":"Kirito","text":"Guess what, Asuna?\nI think I've figured out this\ncastle's dark secret...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你猜怎么着，亚丝娜？我想我已经发现了这座城堡的黑暗秘密......"},{"uid":"410400701:98:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":99,"order":99,"actions":[{"uid":"410400701:99:1","speaker":"Alice","text":"Is the left corridor clear?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"左边走廊畅通吗？"},{"uid":"410400701:99:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":100,"order":100,"actions":[{"uid":"410400701:100:1","speaker":"Asuna","text":"Yup, Kirito and I handled it.\nEverything okay over here?","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是的，是我和桐人处理的。这里一切还好吗？"},{"uid":"410400701:100:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":101,"order":101,"actions":[{"uid":"410400701:101:1","speaker":"Eugeo","text":"Yeah, somehow. But wow...\nThere's a lot of strange and\nsurprising monsters in here, huh?","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是的，不知何故。但是哇……这里有很多奇怪而令人惊讶的怪物，是吗？"},{"uid":"410400701:101:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":102,"order":102,"actions":[{"uid":"410400701:102:1","speaker":"Eugeo","text":"This might sound odd, but I'm\nhaving fun! I feel like I see\nsomething new around every corner!","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"这可能听起来很奇怪，但我玩得很开心！我觉得我在每个角落都看到了新的东西！"}]},{"id":103,"order":103,"actions":[{"uid":"410400701:103:1","speaker":"Alice","text":"Please, can you talk some sense\ninto him? He's been acting like\nthis is for the past hour.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"拜托，你能跟他讲讲道理吗？过去一个小时他一直表现得像这样。"},{"uid":"410400701:103:2","speaker":"Eugeo","text":"","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":104,"order":104,"actions":[{"uid":"410400701:104:1","speaker":"Kirito","text":"Ha ha... Has he, now...?","pose":100115042,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈……他现在……？"},{"uid":"410400701:104:2","speaker":"Asuna","text":"","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":105,"order":105,"actions":[{"uid":"410400701:105:1","speaker":"Eugeo","text":"Sorry, Alice. I'll be more serious\nfrom here on out. Especially after\nwhat just happened.","pose":105302022,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"对不起，爱丽丝。从现在开始我会更加认真的。尤其是在刚刚发生了那件事之后。"},{"uid":"410400701:105:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":106,"order":106,"actions":[{"uid":"410400701:106:1","speaker":"Asuna","text":"After what? What happened?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"之后呢？发生了什么？"},{"uid":"410400701:106:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":107,"order":107,"actions":[{"uid":"410400701:107:1","speaker":"Alice","text":"We ran into another party.\nThey were fairies, like you.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我们又遇到了。他们和你一样都是仙女。"},{"uid":"410400701:107:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":108,"order":108,"actions":[{"uid":"410400701:108:1","speaker":"Kirito","text":"Really?!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"真的吗？！"},{"uid":"410400701:108:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":109,"order":109,"actions":[{"uid":"410400701:109:1","speaker":"Kirito","text":"I can't believe another group\nmanaged to make it this far\nalready.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我不敢相信还有一个团队已经做到了这一步。"},{"uid":"410400701:109:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":110,"order":110,"actions":[{"uid":"410400701:110:1","speaker":"Eugeo","text":"They were fierce warriors,\nand strong. We can't let ourselves\ngrow complacent.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"他们是凶猛的战士，而且很强壮。我们不能让自己沾沾自喜。"},{"uid":"410400701:110:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":111,"order":111,"actions":[{"uid":"410400701:111:1","speaker":"Alice","text":"Do you think they're after the\nDivine Object too?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你觉得他们也在追神器吗？"},{"uid":"410400701:111:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":112,"order":112,"actions":[{"uid":"410400701:112:1","speaker":"Kirito","text":"Most likely. It looks like we'll\nhave to pick up the pace.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"很有可能。看来我们得加快步伐了。"},{"uid":"410400701:112:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":113,"order":113,"actions":[{"uid":"410400701:113:1","speaker":"Kirito","text":"If someone beats us to the punch\nlike back in Leprechaun territory,\nit'll be a big pain.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"如果有人像小矮妖领域那样抢先一步，那就太痛苦了。"}]},{"id":114,"order":114,"actions":[{"uid":"410400701:114:1","speaker":"Kirito","text":"Come on! Let's get a move on!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"加油！让我们继续前进吧！"},{"uid":"410400701:114:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":115,"order":115,"actions":[{"uid":"410400701:115:1","speaker":"Alice","text":"Hyaaah!","pose":10540101,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"哈啊！"}]},{"id":116,"order":116,"actions":[{"uid":"410400701:116:1","speaker":"Demon","text":"Grrack!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"恶魔","text_zh":"天哪！"}]},{"id":117,"order":117,"actions":[{"uid":"410400701:117:1","speaker":"Eugeo","text":"Alice, you finished over there?","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"爱丽丝，你那边吃完了吗？"},{"uid":"410400701:117:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":118,"order":118,"actions":[{"uid":"410400701:118:1","speaker":"Alice","text":"Of course. No evil can withstand\nmy righteous wrath.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"当然。没有任何邪恶能够抵挡我正义的愤怒。"}]},{"id":119,"order":119,"actions":[{"uid":"410400701:119:1","speaker":"Alice","text":"Now, let's regroup with Kirito and\nAsuna before we challenge the\nnext set of enemies.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"现在，我们先和桐人、亚丝娜重新集结，然后再挑战下一批敌人。"}]},{"id":120,"order":120,"actions":[{"uid":"410400701:120:1","speaker":"Eugeo","text":"Yeah, that's a-huh?","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是啊，是啊？"}]},{"id":121,"order":121,"actions":[{"uid":"410400701:121:1","speaker":"Player","text":"Hey, fancy seeing you two again.","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"嘿，很高兴再次见到你们两个。"}]},{"id":122,"order":122,"actions":[{"uid":"410400701:122:1","speaker":"Alice","text":"I remember you from before...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我以前就记得你……"}]},{"id":123,"order":123,"actions":[{"uid":"410400701:123:1","speaker":"Player","text":"Looks like you guys are making\npretty good progress yourselves.","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"看来你们的进步还不错啊。"}]},{"id":124,"order":124,"actions":[{"uid":"410400701:124:1","speaker":"Player","text":"We'll have to hurry up before\nyou beat us to the reward.","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"在你抢先一步获得奖励之前，我们必须抓紧时间。"}]},{"id":125,"order":125,"actions":[{"uid":"410400701:125:1","speaker":"Eugeo","text":"You plan on claiming the Divine\nObject as your own?","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你打算将神物据为己有吗？"}]},{"id":126,"order":126,"actions":[{"uid":"410400701:126:1","speaker":"Player","text":"Divine Object...? You mean the\nquest reward? Yeah, for sure.\nIt looks super rare.","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"神器...?你说的是任务奖励吗？是的，当然。看起来超级罕见。"}]},{"id":127,"order":127,"actions":[{"uid":"410400701:127:1","speaker":"Alice","text":"This tale of a great reward\nawaiting he who cleanses this\ncastle... It IS true, right?","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"这个关于净化这座城堡的人将获得巨大奖励的故事……是真的吧？"}]},{"id":128,"order":128,"actions":[{"uid":"410400701:128:1","speaker":"Eugeo","text":"A-Alice? But-","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"A-爱丽丝？但是——"}]},{"id":129,"order":129,"actions":[{"uid":"410400701:129:1","speaker":"Alice","text":"I trust Kirito. Nevertheless, our\nenemies could be deceiving him\ntoo. It's worth confirming.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我信任桐人。然而，我们的敌人也可能欺骗他。值得确认一下。"}]},{"id":130,"order":130,"actions":[{"uid":"410400701:130:1","speaker":"Eugeo","text":"R-Right... Good thinking...","pose":105302082,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"R-对……好想……"}]},{"id":131,"order":131,"actions":[{"uid":"410400701:131:1","speaker":"Player","text":"The info on the reward?\nWell, yeah... I'm pretty sure\nit's legit.","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"奖励信息？嗯，是的...我很确定这是合法的。"}]},{"id":132,"order":132,"actions":[{"uid":"410400701:132:1","speaker":"Player","text":"I mean, it was an official\nannouncement. They don't\nfake that stuff.","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"我的意思是，这是官方公告。他们不会伪造那些东西。"}]},{"id":133,"order":133,"actions":[{"uid":"410400701:133:1","speaker":"Eugeo","text":"Phew, that's a relief. It looks\nlike this time our information\nis trustworthy.","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"唷，这下松了一口气。看来这次我们的信息是可信的。"}]},{"id":134,"order":134,"actions":[{"uid":"410400701:134:1","speaker":"Alice","text":"Yes, that is a relief. However...\nI feel we should tell them what\nwe know of the Divine Objects.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"是的，这真是一种解脱。然而……我觉得我们应该告诉他们我们对神器的了解。"}]},{"id":135,"order":135,"actions":[{"uid":"410400701:135:1","speaker":"Eugeo","text":"You mean-","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你的意思是——"}]},{"id":136,"order":136,"actions":[{"uid":"410400701:136:1","speaker":"Alice","text":"If we do, then perhaps they'll\ngive up trying to claim it.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"如果我们这么做了，那么也许他们就会放弃尝试。"}]},{"id":137,"order":137,"actions":[{"uid":"410400701:137:1","speaker":"Eugeo","text":"...Yes, you're right. But Kirito\ntold us we should try to avoid\ntalking to other fairies...","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"……是的，你说得对。但桐人告诉我们应该尽量避免与其他仙女交谈......"}]},{"id":138,"order":138,"actions":[{"uid":"410400701:138:1","speaker":"Eugeo","text":"What he says makes sense.\nWe're from another world, after\nall. It could cause problems.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"他说的有道理。毕竟我们来自另一个世界。这可能会导致问题。"}]},{"id":139,"order":139,"actions":[{"uid":"410400701:139:1","speaker":"Alice","text":"True... I agree that we should\navoid unnecessary contact\nwherever possible.","pose":10540106,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"确实……我同意我们应该尽可能避免不必要的接触。"}]},{"id":140,"order":140,"actions":[{"uid":"410400701:140:1","speaker":"Alice","text":"Perhaps we should confer with\nKirito and Asuna before we take\nany further action.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"也许我们应该先与桐人和亚丝娜商量后再采取行动。"}]},{"id":141,"order":141,"actions":[{"uid":"410400701:141:1","speaker":"Eugeo","text":"Yeah, I think that's wise. I bet\nthey would handle it better than\nus, anyway.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是的，我认为这是明智的。无论如何，我敢打赌他们会比我们处理得更好。"}]},{"id":142,"order":142,"actions":[{"uid":"410400701:142:1","speaker":"Alice","text":"Understood.\nYou there. We apologize for taking\nup your time. We will withdraw.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"明白了。你在那里。对于占用您的时间，我们深表歉意。我们将撤退。"}]},{"id":143,"order":143,"actions":[{"uid":"410400701:143:1","speaker":"Player","text":"Uh...sure?\nGood luck, and see you around.","pose":2,"background":"","item":"","illustration":"","speaker_zh":"玩家","text_zh":"呃……确定吗？祝你好运，再见。"}]},{"id":144,"order":144,"actions":[{"uid":"410400701:144:1","speaker":"Kirito","text":"...","pose":10011507,"background":"bg_event_devil_castle_01","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."},{"uid":"410400701:144:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400701:144:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":145,"order":145,"actions":[{"uid":"410400701:145:1","speaker":"Asuna","text":"Hey Kirito... Now that Alice and\nEugeo aren't here, there's\nsomething I want to talk about.","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嘿桐人...现在爱丽丝和尤吉欧不在，我有件事想谈谈。"}]},{"id":146,"order":146,"actions":[{"uid":"410400701:146:1","speaker":"Asuna","text":"The Divine Object's curse created\nthis whole castle, didn't it?","pose":10020906,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"神器的诅咒创造了整座城堡，不是吗？"}]},{"id":147,"order":147,"actions":[{"uid":"410400701:147:1","speaker":"Kirito","text":"It's not one hundred percent\ncertain, but it is very likely.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"虽然不是百分百确定，但是很有可能。"}]},{"id":148,"order":148,"actions":[{"uid":"410400701:148:1","speaker":"Asuna","text":"B-But...the curse usually just\nsummons hordes of powerful\nmonsters, right?","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"可是、但是……诅咒通常只是召唤出一大群强大的怪物，对吧？"}]},{"id":149,"order":149,"actions":[{"uid":"410400701:149:1","speaker":"Asuna","text":"I find it hard to believe it's\nstrong enough to summon a\nwhole castle out of thin air...","pose":100209032,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我很难相信它竟然强大到可以凭空召唤出一整座城堡……"}]},{"id":150,"order":150,"actions":[{"uid":"410400701:150:1","speaker":"Yui","text":"I have a question. Are you using\nthe amulet Liz gave you?","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"我有一个问题。您正在使用莉兹给您的护身符吗？"}]},{"id":151,"order":151,"actions":[{"uid":"410400701:151:1","speaker":"Yui","text":"I believe it was supposed to\nweaken the curse's power.","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"我认为它应该削弱诅咒的力量。"}]},{"id":152,"order":152,"actions":[{"uid":"410400701:152:1","speaker":"Kirito","text":"Yeah, that's what we thought,\nbut I guess it's run out of juice.\nI don't think it's working.","pose":100115022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是的，我们也是这么想的，但我猜它已经没电了。我认为这不起作用。"}]},{"id":153,"order":153,"actions":[{"uid":"410400701:153:1","speaker":"Kirito","text":"But there's something that bothers\nme even more about all of this.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是这一切让我更烦恼。"}]},{"id":154,"order":154,"actions":[{"uid":"410400701:154:1","speaker":"Kirito","text":"Why is a Divine Object the reward\nfor the Halloween event in the\nfirst place?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"为什么万圣节活动的奖励是神器呢？"}]},{"id":155,"order":155,"actions":[{"uid":"410400701:155:1","speaker":"Asuna","text":"Hey, that's a good point!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嘿，说得好！"}]},{"id":156,"order":156,"actions":[{"uid":"410400701:156:1","speaker":"Kirito","text":"Our working theory right now is\nthat people from Alice's world\nstressed the system when they","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们现在的工作理论是，爱丽丝世界的人在他们"}]},{"id":157,"order":157,"actions":[{"uid":"410400701:157:1","speaker":"Kirito","text":"came here, and Cardinal tried to\ncope by creating the Divine\nObjects.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"来到这里，卡迪纳尔试图通过创造神物来应对。"}]},{"id":158,"order":158,"actions":[{"uid":"410400701:158:1","speaker":"Kirito","text":"So isn't it strange that one is\nnow the Halloween event's unique\nreward?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那么现在万圣节活动的唯一奖励是不是很奇怪呢？"}]},{"id":159,"order":159,"actions":[{"uid":"410400701:159:1","speaker":"Asuna","text":"Yeah. We assumed that only people\npartying with Alice and Eugeo-us-\ncould do Divine Object quests.","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯。我们假设只有与爱丽丝和尤吉欧-us- 组队的人才能执行神器任务。"}]},{"id":160,"order":160,"actions":[{"uid":"410400701:160:1","speaker":"Asuna","text":"But if one of them is a public\nevent's reward, that shoots a big\nfat hole in our theory, huh?","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但是如果其中一个是公共活动的奖励，那就在我们的理论中造成了一个大漏洞，对吧？"}]},{"id":161,"order":161,"actions":[{"uid":"410400701:161:1","speaker":"Kirito","text":"Come to think of it, other players\nwere able to mess with our quest\nin the Leprechaun territory too.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"想想看，其他玩家也能扰乱我们在小矮妖领地的任务。"}]},{"id":162,"order":162,"actions":[{"uid":"410400701:162:1","speaker":"Kirito","text":"Maybe the rules governing the\nDivine Objects have changed\nsince Alice and Eugeo appeared?","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也许自从爱丽丝和尤吉欧出现之后，神器的规则就发生了变化？"}]},{"id":163,"order":163,"actions":[{"uid":"410400701:163:1","speaker":"Asuna","text":"Changed? What do you mean?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"变了？你是什​​么意思？"}]},{"id":164,"order":164,"actions":[{"uid":"410400701:164:1","speaker":"Kirito","text":"The longer Alice and Eugeo are\nhere, the more entangled they\nbecome with our world.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"爱丽丝和尤吉欧在这里呆得越久，他们与我们的世界就越纠缠。"}]},{"id":165,"order":165,"actions":[{"uid":"410400701:165:1","speaker":"Kirito","text":"Perhaps the system is converting\ntheir data. Turning them native,\nso to speak.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"可能系统正在转换他们的数据。可以这么说，将它们变成本地人。"}]},{"id":166,"order":166,"actions":[{"uid":"410400701:166:1","speaker":"Asuna","text":"But... Isn't that dangerous for\nthem?","pose":100209082,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但是……这对他们来说不是很危险吗？"}]},{"id":167,"order":167,"actions":[{"uid":"410400701:167:1","speaker":"Kirito","text":"Yeah, I think so. If the process\ngoes far enough, they might never\nbe able to return home...","pose":100115022,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊，我也这么认为。如果这个过程走得太远，他们可能永远无法回家......"}]},{"id":168,"order":168,"actions":[{"uid":"410400701:168:1","speaker":"Asuna","text":"We can't let that happen!","pose":100209092,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们不能让这种事发生！"}]},{"id":169,"order":169,"actions":[{"uid":"410400701:169:1","speaker":"Kirito","text":"Well, remember. This is just a\nwild guess. Let's not mention it\nto them until we have proof.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯，记住了。这只是一个疯狂的猜测。在我们有证据之前我们不要向他们提起这件事。"}]},{"id":170,"order":170,"actions":[{"uid":"410400701:170:1","speaker":"Asuna","text":"Y-Yeah... Well, there are seven\nDivine Objects, and we have three\nnow...","pose":100209062,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是、是啊……嗯，神器有七件，现在有三件……"}]},{"id":171,"order":171,"actions":[{"uid":"410400701:171:1","speaker":"Asuna","text":"Let's hurry up and find the other\nfour.","pose":100209062,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们赶紧去找另外四个人吧。"}]},{"id":172,"order":172,"actions":[{"uid":"410400701:172:1","speaker":"Kirito","text":"Hmmm... Yeah, this might end up\nbeing a big waste of time...","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……是的，这可能会浪费很多时间……"}]},{"id":173,"order":173,"actions":[{"uid":"410400701:173:1","speaker":"Kirito","text":"But I think we should go check\nthat area out, just in case.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不过我觉得我们应该去看看那个地方，以防万一。"}]},{"id":174,"order":174,"actions":[{"uid":"410400701:174:1","speaker":"Asuna","text":"You think we'll find Urdr there?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你觉得我们会在那里找到乌尔德吗？"}]},{"id":175,"order":175,"actions":[{"uid":"410400701:175:1","speaker":"Kirito","text":"Maybe. I do know I've got a lot of\nquestions for her. What these\nDivine Objects are, for starters.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也许吧。我知道我有很多问题要问她。首先，这些神器是什么。"}]}]};
